  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  // --- Global Timing ---
  // Normalize frame to 0-1 range for easier scene management or strict frame counts
  // Total Frames: ~600 (at 30fps)
  // Scene 1: 0 - 160 (Creation)
  // Scene 2: 160 - 320 (Responsive)
  // Scene 3: 320 - 480 (Optimization Tags)
  // Scene 4: 480 - end (Logo/Final)

  const SCENE_1_END = 160;
  const SCENE_2_END = 320;
  const SCENE_3_END = 480;

  // --- Derived Styles ---
  const bgStyle = transparentBackground ? "transparent" : backgroundColor;
  const titleStyle: React.CSSProperties = {
    fontFamily: "Inter",
    fontWeight: 700,
    fontSize: width * 0.05,
    color: textColor,
    textAlign: "center",
    position: "absolute",
    width: "100%",
    top: height * 0.15,
    zIndex: 100,
  };

  const subtitleStyle: React.CSSProperties = {
    fontFamily: "Inter",
    fontWeight: 400,
    fontSize: width * 0.025,
    color: textColor,
    opacity: 0.6,
    textAlign: "center",
    position: "absolute",
    width: "100%",
    top: height * 0.22,
    zIndex: 100,
  };

  // --- Animation Helpers ---
  const springIn = (delay: number) =>
    spring({
      frame: frame - delay,
      fps,
      config: { damping: 12 },
    });

  // --- Scene 1: Stack Up (0-160) ---
  // Three "input" cards stacking up
  const card1Progress = springIn(10);
  const card2Progress = springIn(20);
  const card3Progress = springIn(30);

  // Merge into one card at end of S1
  const mergeProgress = interpolate(frame, [100, 140], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.bezier(0.25, 1, 0.5, 1),
  });

  // Opacity of the "Input" cards as they merge
  const inputCardsOpacity = interpolate(mergeProgress, [0, 0.8], [1, 0]);

  // Main Hero Card scaling up to replace them
  const heroCardScale = interpolate(mergeProgress, [0, 1], [0.8, 1]);
  const heroCardOpacity = interpolate(mergeProgress, [0, 0.5], [0, 1]);

  // --- Scene 2: Responsive Resize (160-320) ---
  // Morph width from Desktop -> Tablet -> Mobile
  // Times: 180 (start), 220 (tablet), 260 (mobile)
  const resizeProgress = interpolate(frame, [180, 220, 260], [0, 0.5, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.ease),
  });

